import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.next();
        StringBuilder decoded = new StringBuilder();
        decoded.append(s.charAt(0));
        int atFlag = 0;
        int i = 1;
        while (i < s.length()) {
            if (i + 2 < s.length()) {
                String threeCharSeq = s.substring(i, i + 3);
                if (threeCharSeq.equals("dot") && i != s.length() - 3) {
                    i += 3;
                    decoded.append('.');
                    continue;
                }
            }
            if (i + 1 < s.length()) {
                String twoCharSeq = s.substring(i, i + 2);
                if (twoCharSeq.equals("at") && atFlag == 0) {
                    atFlag = 1;
                    i += 2;
                    decoded.append('@');
                    continue;
                }
            }
            decoded.append(s.charAt(i));
            i++;
        }
        System.out.println(decoded.toString());
        scanner.close();
    }
}
